steps.script:
var p = PhaseManager.get_current_phase_instance()
for i in range(4):
	if p == null or not p.has_pending_stratagem_window():
		break
	var w = p.get_pending_stratagem_window()
	if str(w.get("window_id", "")) != "movement_phase_start":
		break
	NetworkIntegration.route_action({"type": "DECLINE_WINDOW_STRATAGEM", "player": int(w.get("player", 1)), "window_id": str(w.get("window_id", ""))})
return p != null and not p.has_pending_stratagem_window()

var u = GameState.get_unit("U_CUSTODIAN_GUARD_B")
var ok := true
for m in u.models:
	if not m.get("alive", true) or m.get("position", null) == null:
		continue
	var p = m.position
	var r = NetworkIntegration.route_action({"type": "STAGE_MODEL_MOVE", "player": 2, "actor_unit_id": "U_CUSTODIAN_GUARD_B", "payload": {"model_id": str(m.id), "dest": [float(p.x) + 0.0, float(p.y) + -200.0], "rotation": float(m.get("rotation", 0.0))}})
	if not r.get("success", false):
		print("[wp-g2] stage failed ", m.id, " ", r.get("error", r.get("errors", "")))
		ok = false
tree.current_scene._recreate_unit_visuals()
return ok
